parameters.jsCode:
// Add Lookups — fill SAP customer code, profit centre and product line from the ZSD log and the Tableau extract.
// Matching is on invoice number only. Nothing is guessed: no match = the value stays empty.
// Values found on an earlier upload are kept, so an invoice that is no longer in a later Tableau extract keeps its codes.
const TABLEAU_COMPANY_CODES = ['3060', '3485', '3487', 'G367']; // other company codes in the Tableau extract are ignored
// Clearwater (G367): product line PQP when Tableau does not give one
const CLEARWATER = { companyCode: 'G367', Product_Line: 'PQP', Business_Type: 'MANUFACTURING' };
const SOURCES = [ // the read steps, in order of preference for the SAP customer code
  { step: 'Read ZSD Log', label: 'ZSD' },
  { step: 'Read ZSD 2025 Sheet', label: 'ZSD' },
  { step: 'Read Tableau Extract', label: 'Tableau' },
];

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
// cleaned value for matching: "0007001212645", " 7,001,212,645 ", "'7001212645" and 7001212645.0 all become 7001212645
const key = (v) => {
  let t = String(v ?? '').trim().replace(/^'/, '').replace(/\.0+$/, '');
  if (/^[\d\s,]+$/.test(t)) t = t.replace(/[\s,]/g, '').replace(/^0+(?=\d)/, '');
  return t;
};
const tidy = (v) => String(v ?? '').replace(/\s+/g, ' ').trim().toUpperCase(); // profit centre as text, e.g. GPJ908
const rows = $('Clean Rows').all().map((i) => ({ ...i.json, Sales_Org: null, SAP_Customer_Code: null, Profit_Center: null, Product_Line: null, Business_Type: null, Standard_Category: null }));
const wanted = new Set(rows.map((r) => key(r.Invoice)));

// rows from one read step (a missing file or sheet gives an error item, which is skipped)
const readRows = (step) => {
  try { return $(step).all().map((i) => i.json).filter((j) => j && !j.error && Object.keys(j).length > 1); }
  catch (e) { return []; }
};
// the column whose values match the most tracker invoice numbers is the invoice column
const invoiceColumn = (data) => {
  const hits = {};
  for (const r of data) for (const [h, v] of Object.entries(r)) if (wanted.has(key(v))) hits[h] = (hits[h] || 0) + 1;
  return Object.entries(hits).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] ?? null;
};
// the column that passes `test` for the most rows
const columnBy = (data, test) => {
  const counts = {};
  for (const r of data) for (const [h, v] of Object.entries(r)) if (test(norm(h), v) && key(v)) counts[h] = (counts[h] || 0) + 1;
  return Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] ?? null;
};
const isCustomerCode = (h, v) => /customer|sold to|payer/.test(h) && !/name|key|group|country|type/.test(h)
  && /^[A-Za-z]?\d{3,}$/.test(key(v)); // e.g. 89598 or 160026
const isProfitCentre = (h) => /profit/.test(h);
const isProductLine = (h) => /product/.test(h) && !/desc|name/.test(h); // e.g. PTI, AIS, PTR, GIS

const found = { customer: new Map(), profit: new Map(), product: new Map(), business: new Map(), salesOrg: new Map() };
// activity (Manufacturing / Services / Trading): Tableau "Nature of Activities PL" (the one that goes with the product line)
const isBusinessType = (h) => /nature/.test(h);
const SALES_ORGS = ['G36C', 'GS5C']; // sales orgs of G367 (same list as COMPANY_CODE_FIX in "Clean Rows")
const isSalesOrg = (h) => /sales org|sorg/.test(h);

// the tracker may hold the sales org in its company code column: keep it before it was changed to G367
{
  const raw = $('Read Tracker Sheet').all().map((i) => i.json);
  const heads = [...new Set(raw.flatMap((r) => Object.keys(r || {})))];
  const ccHead = heads.find((h) => ['company code', 'coco', 'co code', 'company_code'].includes(norm(h)));
  const invHead = heads.find((h) => ['invoice', 'invoice no', 'invoice number', 'invoice #', 'inv no'].includes(norm(h)));
  if (ccHead && invHead) {
    for (const r of raw) {
      const so = String(r[ccHead] ?? '').trim().toUpperCase();
      if (SALES_ORGS.includes(so)) found.salesOrg.set(key(r[invHead]), so);
    }
  }
}
const notes = [];
for (const { step, label } of SOURCES) {
  let data = readRows(step);
  if (label === 'Tableau') { // keep only the company codes we report on
    const ccCol = columnBy(data, (h) => h === 'company code');
    if (ccCol) data = data.filter((r) => TABLEAU_COMPANY_CODES.includes(tidy(r[ccCol])));
  }
  if (!data.length) continue;
  const inv = invoiceColumn(data);
  if (!inv) { notes.push(`${step}: no invoice numbers matched the tracker`); continue; }
  const cust = columnBy(data, isCustomerCode);
  const prof = label === 'Tableau' ? columnBy(data, isProfitCentre) : null;
  // a heading with "line" in it wins for product line ("Product Line" over "Product")
  const prod = label === 'Tableau' ? (columnBy(data, (h) => isProductLine(h) && /line/.test(h)) || columnBy(data, isProductLine)) : null;
  const biz = label === 'Tableau' ? (columnBy(data, (h) => isBusinessType(h) && /\bpl\b|product/.test(h)) || columnBy(data, isBusinessType)) : null;
  const sorg = label === 'ZSD' ? columnBy(data, (h, v) => isSalesOrg(h) && SALES_ORGS.includes(tidy(v))) : null;
  let matched = 0;
  for (const r of data) {
    const k = key(r[inv]);
    if (!wanted.has(k)) continue;
    matched++;
    if (cust && key(r[cust]) && !found.customer.has(k)) found.customer.set(k, key(r[cust]));
    if (prof && key(r[prof]) && !found.profit.has(k)) found.profit.set(k, tidy(r[prof]));
    if (prod && key(r[prod]) && !found.product.has(k)) found.product.set(k, tidy(r[prod]));
    if (biz && key(r[biz]) && !found.business.has(k)) found.business.set(k, tidy(r[biz]));
    if (sorg && SALES_ORGS.includes(tidy(r[sorg])) && !found.salesOrg.has(k)) found.salesOrg.set(k, tidy(r[sorg]));
  }
  notes.push(`${step}: ${matched} matching rows (invoice column "${inv}"` +
    (cust ? `, customer code "${cust}"` : ', no customer code column found') +
    (label === 'Tableau' ? `, profit centre ${prof ? `"${prof}"` : 'not found'}, product line ${prod ? `"${prod}"` : 'not found'}, activity ${biz ? `"${biz}"` : 'not found'})` : ')'));
}

// values saved on earlier uploads (read by "Check Table" before anything is changed)
const before = new Map();
for (const { json: t } of $('Check Table').all()) if (t && t.Invoice != null) before.set(key(t.Invoice), t);

for (const r of rows) {
  const k = key(r.Invoice);
  const old = before.get(k) || {};
  r.SAP_Customer_Code = found.customer.get(k) ?? old.SAP_Customer_Code ?? null;
  r.Profit_Center = found.profit.get(k) ?? old.Profit_Center ?? null;
  r.Product_Line = found.product.get(k) ?? old.Product_Line ?? null;
  r.Business_Type = found.business.get(k) ?? old.Business_Type ?? null;
  if (String(r.Company_Code) === CLEARWATER.companyCode) {
    r.Product_Line = r.Product_Line ?? CLEARWATER.Product_Line;
    r.Business_Type = r.Business_Type ?? CLEARWATER.Business_Type;
    r.Sales_Org = found.salesOrg.get(k) ?? old.Sales_Org ?? null;
  }
}
// standard blocker category: fixed rules / earlier uploads ("Standard Blockers"), the rest from the AI (only allowed names)
{
  const std = (() => { try { return $('Standard Blockers').first().json; } catch (e) { return null; } })();
  if (std) {
    let aiPicks = {};
    try {
      const raw = String($('AI Blocker Classifier').first().json.text ?? $('AI Blocker Classifier').first().json.output ?? '');
      const m = raw.replace(/```[a-z]*\n?/gi, '').match(/\[[\s\S]*\]/);
      for (const x of (m ? JSON.parse(m[0]) : [])) {
        const name = std.categories.find((c) => c.toLowerCase() === String(x && x.category || '').trim().toLowerCase());
        if (x && Number.isFinite(+x.id)) aiPicks[+x.id] = name || 'Other'; // a name outside the list becomes "Other"
      }
    } catch (e) { aiPicks = {}; }
    let ai = 0; let aiMissing = 0;
    for (const r of rows) {
      const res = std.result[String(r.Invoice)];
      if (!res) continue;
      if (res.category) { r.Standard_Category = res.category; continue; }
      const pick = aiPicks[std.keyToId[res.key]];
      r.Standard_Category = pick || 'Other';
      if (pick) ai++; else aiMissing++;
    }
    if (std.itemCount || aiMissing) notes.push(`blocker wording classified by AI: ${ai}${aiMissing ? `, ${aiMissing} set to "Other" (AI gave no answer)` : ''}`);
  }
}
// which columns were used is shown on the Done page; "_lookupNotes" is removed again before saving
if (rows.length) rows[0]._lookupNotes = notes.length ? notes.join(' · ') : 'no ZSD log or Tableau extract uploaded';
return rows.map((json) => ({ json }));

// Safety Check – runs BEFORE the table is emptied.
// If anything is wrong it stops here with a clear message, and the Data Table is left exactly as it was.
const rows = $('Add Lookups').all();
if (!rows.length) {
  throw new Error('No rows with an invoice number were found in the file. Nothing was changed.');
}
const columns = Object.keys(rows[0].json).filter((k) => !k.startsWith('_')); // the columns that will be saved
const sample = $('Check Table').first().json || {}; // an existing row of the Data Table (empty if the table is empty)
const tableColumns = Object.keys(sample);
if (tableColumns.length) {
  const missing = columns.filter((c) => !tableColumns.includes(c));
  if (missing.length) {
    throw new Error(`The Data Table has no column called: ${missing.join(', ')}. ` +
      'Check that "Check Table", "Clear Table" and "Save All Rows" all point to the right Data Table, ' +
      'or add the missing column(s) to the Data Table (type: string). Nothing was changed.');
  }
}
return [{ json: { rowsToSave: rows.length, tableHadRows: tableColumns.length > 0 } }];

// Rows to Save — after the table is cleared, pass all rows (with the looked-up codes) to the bulk save.
// Helper fields starting with "_" are not saved.
return $('Add Lookups').all().map((i) => ({
  json: Object.fromEntries(Object.entries(i.json).filter(([k]) => !k.startsWith('_'))),
}));

// Summarise Upload — counts and data quality checks for the confirmation page.
// Fixed rules only (no clock, no randomness): the same file always gives the same result.
const KEY = 'Invoice';
const KEY_ALIASES = ['invoice', 'invoice no', 'invoice number', 'invoice #', 'inv no']; // keep in step with Clean Rows
const EARLIEST_DATE = '2020-01-01';
const DATE_COLUMNS = ['Received_Date', 'Allocated_Date', 'Invoice_Date'];
const LIST_LIMIT = 10;
const FILE_NAME = $('Upload Tracker').first().binary?.Tracker_File?.fileName ?? 'tracker';

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const keyNames = new Set([KEY, ...KEY_ALIASES].map(norm));
const num = (v) => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};

// Raw sheet: blank-key rows and repeated invoices
const raw = $('Read Tracker Sheet').all().map((i) => i.json);
const seen = new Map();
const unreadable = []; // invoice cells that are not a plain number (e.g. "7001 / 7002"): skipped, not guessed
let blank = 0;
for (const r of raw) {
  const h = Object.keys(r).find((k) => keyNames.has(norm(k)));
  const id = h == null ? '' : String(r[h] ?? '').trim();
  if (!/\d/.test(id)) { blank++; continue; } // empty, or a label such as "Total"
  if (!/^\d+(\.0+)?$/.test(id.replace(/[\s,]/g, ''))) { unreadable.push(id); continue; }
  seen.set(id, (seen.get(id) || 0) + 1);
}
const duplicates = [...seen].filter(([, n]) => n > 1).map(([id]) => id).sort();

// Cleaned rows: quality checks
const rows = $('Clean Rows').all().map((i) => i.json);
const isOpen = (r) => /pend|hold|open|progress|query|block/i.test(String(r.Status || ''));
const checks = {
  'missing value': (r) => num(r.Value) === null,
  'zero or negative value': (r) => num(r.Value) !== null && num(r.Value) <= 0,
  'missing customer': (r) => !r.Customer,
  'missing company code': (r) => !r.Company_Code,
  'no readable date': (r) => DATE_COLUMNS.every((c) => !r[c]),
  [`date before ${EARLIEST_DATE}`]: (r) => DATE_COLUMNS.some((c) => r[c] && r[c] < EARLIEST_DATE),
  'allocated before received': (r) => r.Allocated_Date && r.Received_Date && r.Allocated_Date < r.Received_Date,
  // status / reason entries still to be filled in (only checked when the tracker has these columns)
  ...(rows.some((r) => 'Status' in r) ? {
    'no status': (r) => !r.Status,
    'pending status but no reason': (r) => isOpen(r) && !r.Pending_Reason && !r.Pending_Category,
    'pending status but no category': (r) => isOpen(r) && !r.Pending_Category && !!r.Pending_Reason,
    'pending status but no owner (Uploaded by)': (r) => isOpen(r) && !r.Uploaded_By,
    'pending status but an upload date': (r) => isOpen(r) && !!r.Upload_Date,
    'completed status but no upload date or TAT': (r) => r.Status === 'Completed' && !r.Upload_Date && (r.Tracker_TAT === null || r.Tracker_TAT === undefined || r.Tracker_TAT === ''),
  } : {}),
};
const issues = {};
for (const [label, test] of Object.entries(checks)) {
  const ids = rows.filter(test).map((r) => String(r[KEY]));
  if (ids.length) issues[label] = { count: ids.length, examples: ids.slice(0, LIST_LIMIT) };
}

const fmt = (n) => n.toLocaleString('en-US');
// how many rows were actually written (only present when the "Compare with Table" step is used)
const written = (() => {
  try { return $('Compare with Table').all().filter((i) => i.json.Invoice !== undefined && i.json.Invoice !== null && i.json.Invoice !== '').length; }
  catch (e) { return null; }
})();
const parts = written === null
  ? [`${fmt(rows.length)} invoices saved from ${fmt(raw.length)} rows`]
  : [`${fmt(rows.length)} invoices in the file (${fmt(raw.length)} rows) · ${fmt(written)} new or changed rows saved, the rest were already up to date`];
if (blank) parts.push(`${fmt(blank)} blank or total rows skipped`);
if (unreadable.length) {
  parts.push(`${fmt(unreadable.length)} rows skipped because the invoice number is not a plain number: ` +
    unreadable.slice(0, LIST_LIMIT).join(', ') + (unreadable.length > LIST_LIMIT ? ', …' : ''));
}
if (duplicates.length) {
  parts.push(`${fmt(duplicates.length)} invoices appear more than once (last row kept): ` +
    duplicates.slice(0, LIST_LIMIT).join(', ') + (duplicates.length > LIST_LIMIT ? ', …' : ''));
}
for (const [label, { count, examples }] of Object.entries(issues)) {
  parts.push(`${fmt(count)} with ${label} (e.g. ${examples.slice(0, 3).join(', ')})`);
}
// SAP customer code / profit centre coverage (only when the "Add Lookups" step is used)
try {
  const looked = $('Add Lookups').all().map((i) => i.json);
  const pcRows = looked;
  parts.push(`SAP customer code found for ${fmt(looked.filter((r) => r.SAP_Customer_Code).length)} of ${fmt(looked.length)} invoices` +
    ` · profit centre found for ${fmt(pcRows.filter((r) => r.Profit_Center).length)} of ${fmt(pcRows.length)}` +
    ` · product line found for ${fmt(pcRows.filter((r) => r.Product_Line).length)} of ${fmt(pcRows.length)} (G367 = PQP if Tableau has none)` +
    ` · sales org found for ${fmt(looked.filter((r) => r.Sales_Org).length)} of ${fmt(looked.filter((r) => String(r.Company_Code) === 'G367').length)} G367 invoices`);
  if (looked[0]?._lookupNotes) parts.push(`Columns used – ${looked[0]._lookupNotes}`);
} catch (e) { /* step not in this workflow */ }
if (!duplicates.length && !unreadable.length && !Object.keys(issues).length) parts.push('no data quality issues found');

return [{
  json: {
    file: FILE_NAME,
    rowsRead: raw.length,
    rowsSaved: rows.length,
    blankRows: blank,
    unreadableInvoices: unreadable,
    duplicateInvoices: duplicates,
    issues,
    message: parts.join(' · '),
  },
}];

// Build Report — incoming volume, watchlist, company code & customer split, weekly/monthly trends,
// workload heatmap and forecast. Fixed rules only: the same data and choices always give the same report.
// The email shows the report; the attached dashboard.html lets you change period / company code / customer.
const RECIPIENTS = ['']; // put your email between the quotes, e.g. ['name.surname@company.com']
const RULES = {
  spike: 1.5, // flag when a customer's invoices are 50%+ above their usual (average of previous 3 periods)
  fall: 0.5, // flag when an active customer falls 50%+ below their usual
  share: 0.2, // flag when one customer is over 20% of the period's value
  slowDays: 3, // flag when average Received → Allocated takes more than 3 days
  minInvoices: 3, // ignore customers with fewer invoices than this for spike / fall / turnaround / portal flags
  // past due needs each customer's payment terms – planned as a later addition, so it is not shown yet
  followUpDays: 2, // a follow-up is due when nothing was done for this many days (last date in "Reason for Pending")
};
const TODAY = new Date().toISOString().slice(0, 10); // days pending are counted up to this date
RULES.today = TODAY;

// ---------- shared helpers (also embedded in the dashboard) ----------
function analyse(all, opts, RULES) {
  const DAY = 86400000;
  const ms = (d) => Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10));
  const iso = (t) => new Date(t).toISOString().slice(0, 10);
  const addDays = (d, n) => iso(ms(d) + n * DAY);
  const weekStart = (d) => addDays(d, -((new Date(ms(d)).getUTCDay() + 6) % 7)); // Monday
  const monthStart = (d) => d.slice(0, 8) + '01';
  const monthEnd = (d) => iso(Date.UTC(+d.slice(0, 4), +d.slice(5, 7), 0));
  const addMonths = (d, n) => iso(Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1 + n, 1));
  const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : 0; };
  const sum = (a, f) => a.reduce((s, r) => s + f(r), 0);

  const dates = all.map((r) => r.d).filter(Boolean).sort();
  if (!dates.length) return { empty: true };
  const first = dates[0];
  const latest = dates[dates.length - 1];

  // ----- period -----
  let from, to, label;
  const type = opts.type || 'Overview';
  if (type === 'Weekly') { from = weekStart(latest); to = addDays(from, 6); label = `Week of ${from}`; }
  else if (type === 'Custom period') {
    from = opts.from || first; to = opts.to || latest; label = `${from} to ${to}`;
  } else { from = monthStart(latest); to = monthEnd(latest); label = type === 'Monthly' ? from.slice(0, 7) : `${from.slice(0, 7)} (month to date)`; }
  if (to < from) [from, to] = [to, from];
  const len = Math.round((ms(to) - ms(from)) / DAY) + 1;
  const shift = (k) => type === 'Weekly' || type === 'Custom period'
    ? [addDays(from, -len * k), addDays(from, -len * (k - 1) - 1)]
    : [addMonths(from, -k), monthEnd(addMonths(from, -k))];

  const cc = String(opts.companyCode || '').trim().toUpperCase();
  const cust = String(opts.customer || '').trim().toUpperCase();
  const pcSel = String(opts.profitCentre || '').trim().toUpperCase();
  const plSel = String(opts.productLine || '').trim().toUpperCase();
  const pcKey = (r) => r.pc || 'NOT FOUND';
  const plKey = (r) => r.pl || 'NOT FOUND';
  const scoped = all.filter((r) => r.d && (!cc || r.cc === cc) && (!cust || r.c.includes(cust))
    && (!pcSel || pcKey(r) === pcSel) && (!plSel || plKey(r) === plSel));
  // pending items and fill-in checks also include rows without any date
  const scopedAny = all.filter((r) => (!cc || r.cc === cc) && (!cust || r.c.includes(cust))
    && (!pcSel || pcKey(r) === pcSel) && (!plSel || plKey(r) === plSel));
  const inRange = (a, b) => scoped.filter((r) => r.d >= a && r.d <= b);
  const cur = inRange(from, to);
  const [pf, pt] = shift(1);
  const prev = inRange(pf, pt);
  // baseline = previous 3 periods, but only those fully covered by data (so the start of the data isn't a fake "spike")
  const base = [1, 2, 3].map((k) => shift(k)).filter(([a]) => a >= first).map(([a, b]) => inRange(a, b));

  const tat = (r) => (r.rd && r.ad ? Math.max(0, Math.round((ms(r.ad) - ms(r.rd)) / DAY)) : null);
  const avgTat = (rows) => { const t = rows.map(tat).filter((x) => x !== null); return t.length ? sum(t, (x) => x) / t.length : null; };
  const channel = (r) => (!r.p ? 'Not recorded' : r.p.includes('@') ? 'Email' : `Portal: ${r.p.split(/[,;]/)[0].trim()}`);
  const groupBy = (rows, key) => {
    const m = new Map();
    for (const r of rows) { const k = key(r); if (!k) continue; const g = m.get(k) || { key: k, n: 0, v: 0, rows: [] }; g.n++; g.v += num(r.v); g.rows.push(r); m.set(k, g); }
    return [...m.values()];
  };
  const byValue = (a, b) => b.v - a.v || String(a.key).localeCompare(String(b.key));
  const change = (now, before) => (before ? (now - before) / before : null);

  const total = { n: cur.length, v: sum(cur, (r) => num(r.v)) };
  const prevTotal = { n: prev.length, v: sum(prev, (r) => num(r.v)) };

  // ----- watchlist -----
  const firstSeen = new Map();
  for (const r of all) if (r.d && (!firstSeen.has(r.c) || r.d < firstSeen.get(r.c))) firstSeen.set(r.c, r.d);
  const watch = [];
  for (const g of groupBy(cur, (r) => r.c).sort(byValue)) {
    const usual = base.length ? sum(base, (rows) => rows.filter((r) => r.c === g.key).length) / base.length : 0;
    const reasons = [];
    if (firstSeen.get(g.key) >= from) reasons.push(['New customer', `first invoice ${firstSeen.get(g.key)}`]);
    else if (g.n >= RULES.minInvoices && usual > 0 && g.n >= usual * RULES.spike) reasons.push(['Volume spike', `${g.n} invoices vs usual ${usual.toFixed(1)}`]);
    if (total.v && g.v / total.v > RULES.share) reasons.push(['High value share', `${(100 * g.v / total.v).toFixed(1)}% of value`]);
    const t = avgTat(g.rows);
    if (g.n >= RULES.minInvoices && t !== null && t > RULES.slowDays) reasons.push(['Slow turnaround', `${t.toFixed(1)} days received → allocated`]);
    const portal = g.rows.filter((r) => channel(r).startsWith('Portal'));
    if (portal.length >= RULES.minInvoices) reasons.push(['Portal submissions', `${portal.length} via ${channel(portal[0]).slice(8)}`]);
    const missing = g.rows.filter((r) => !num(r.v)).length;
    if (missing) reasons.push(['Data issue', `${missing} without a value`]);
    if (reasons.length) watch.push({ customer: g.key, n: g.n, v: g.v, reasons });
  }
  const curCustomers = new Set(cur.map((r) => r.c));
  const usualAll = new Map();
  for (const rows of base) for (const r of rows) usualAll.set(r.c, (usualAll.get(r.c) || 0) + 1 / base.length);
  for (const [c, usual] of [...usualAll].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))) {
    const n = cur.filter((r) => r.c === c).length;
    if (usual >= RULES.minInvoices && n <= usual * RULES.fall) {
      const item = { customer: c, n, v: sum(cur.filter((r) => r.c === c), (r) => num(r.v)), reasons: [[n ? 'Sharp fall' : 'Gone quiet', `${n} invoices vs usual ${usual.toFixed(1)}`]] };
      if (curCustomers.has(c)) { const w = watch.find((x) => x.customer === c); if (w) w.reasons.push(item.reasons[0]); else watch.push(item); } else watch.push(item);
    }
  }

  // ----- trends -----
  const monthsBack = [];
  for (let k = 11; k >= 0; k--) monthsBack.push(addMonths(monthStart(to), -k));
  const monthly = monthsBack.map((m) => { const rows = scoped.filter((r) => r.d >= m && r.d <= monthEnd(m)); return { key: m.slice(0, 7), n: rows.length, v: sum(rows, (r) => num(r.v)) }; })
    .filter((m, i, a) => m.n || a.slice(0, i).some((x) => x.n));
  const weeksBack = [];
  for (let k = 7; k >= 0; k--) weeksBack.push(addDays(weekStart(to), -7 * k));
  const weekly = weeksBack.map((w) => { const rows = scoped.filter((r) => r.d >= w && r.d <= addDays(w, 6)); return { key: w, n: rows.length, v: sum(rows, (r) => num(r.v)) }; });
  const heat = monthsBack.slice(-6).map((m) => {
    const cells = Array.from({ length: 31 }, (_, i) => scoped.filter((r) => r.d.slice(0, 7) === m.slice(0, 7) && +r.d.slice(8, 10) === i + 1).length);
    return { key: m.slice(0, 7), cells };
  });
  const wd = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const last12w = scoped.filter((r) => r.d > addDays(to, -84) && r.d <= to);
  const weekday = wd.map((name, i) => ({ key: name, n: last12w.filter((r) => (new Date(ms(r.d)).getUTCDay() + 6) % 7 === i).length / 12 }));

  // ----- forecast (averages of recent complete periods; range = lowest–highest of those periods) -----
  const doneWeeks = [];
  for (let k = 8; k >= 1; k--) { const w = addDays(weekStart(latest), -7 * k); const rows = scoped.filter((r) => r.d >= w && r.d <= addDays(w, 6)); doneWeeks.push({ n: rows.length, v: sum(rows, (r) => num(r.v)) }); }
  const doneMonths = [];
  for (let k = 3; k >= 1; k--) { const m = addMonths(monthStart(latest), -k); const rows = scoped.filter((r) => r.d >= m && r.d <= monthEnd(m)); doneMonths.push({ n: rows.length, v: sum(rows, (r) => num(r.v)) }); }
  const stat = (a, f) => ({ avg: a.length ? sum(a, f) / a.length : 0, lo: a.length ? Math.min(...a.map(f)) : 0, hi: a.length ? Math.max(...a.map(f)) : 0 });
  const forecast = {
    weekN: stat(doneWeeks, (x) => x.n), weekV: stat(doneWeeks, (x) => x.v),
    monthN: stat(doneMonths, (x) => x.n), monthV: stat(doneMonths, (x) => x.v),
    nextWeeks: [1, 2, 3, 4].map((k) => addDays(weekStart(latest), 7 * k)),
    nextMonth: addMonths(monthStart(latest), 1).slice(0, 7),
  };

  // ----- splits -----
  const companies = groupBy(cur, (r) => r.cc || 'UNKNOWN').sort(byValue).map((g) => ({
    key: g.key, n: g.n, v: g.v, prevN: prev.filter((r) => (r.cc || 'UNKNOWN') === g.key).length,
    top: groupBy(g.rows, (r) => r.c).sort(byValue).slice(0, 5),
  }));
  const split = (keyOf) => groupBy(cur, keyOf).sort(byValue).map((g) => ({
    key: g.key, n: g.n, v: g.v, prevN: prev.filter((r) => keyOf(r) === g.key).length, tat: avgTat(g.rows),
    top: groupBy(g.rows, (r) => r.c).sort(byValue).slice(0, 5),
  }));
  const profitCentres = split(pcKey);
  const productLines = split(plKey);
  // ----- breakdown tree: entity → company code → sales org → (profit centre, product line) -----
  const ENTITY = { '3060': 'LA PRAIRIE (CANADA)', '3487': 'LA PRAIRIE (CANADA)', '3485': 'CHARLEROI', G367: 'CLEARWATER' };
  const LEVEL = {
    entity: { name: 'Entity', of: (r) => ENTITY[r.cc] || (r.cc ? 'OTHER' : '') },
    cc: { name: 'Company code', of: (r) => r.cc || '' },
    so: { name: 'Sales org', of: (r) => r.so || '' },
    pc: { name: 'Profit centre', of: (r) => r.pc || '' },
    pl: { name: 'Product line', of: (r) => r.pl || '' },
  };
  // values of `child` that appear under more than one value of `parent` (checked on all data, not just this period)
  const clashes = (parent, child) => {
    const m = new Map();
    for (const r of scoped) {
      const c = LEVEL[child].of(r); const pv = LEVEL[parent].of(r);
      if (!c || !pv) continue;
      if (!m.has(c)) m.set(c, new Set());
      m.get(c).add(pv);
    }
    return [...m].filter(([, set]) => set.size > 1).map(([c]) => c).sort();
  };
  // order of the two lower levels: the one with the fewest clashes; a tie keeps the expected order (first in the list)
  const ORDERS = [['pc', 'pl'], ['pl', 'pc']];
  const scored = ORDERS.map((o, i) => ({ o, i, n: clashes('cc', o[0]).length + clashes(o[0], o[1]).length }));
  const lower = scored.sort((x, y) => x.n - y.n || x.i - y.i)[0].o;
  const levels = ['entity', 'cc', 'so', ...lower];
  const structure = {
    order: levels.map((k) => LEVEL[k].name),
    // sales org only exists for G367, so the lower levels are checked against the company code
    exceptions: [['entity', 'cc'], ['cc', 'so'], ['cc', lower[0]], [lower[0], lower[1]]]
      .map(([pk, ck]) => ({ parent: LEVEL[pk].name, child: LEVEL[ck].name, values: clashes(pk, ck) }))
      .filter((e) => e.values.length),
  };
  // only overlaps at the top (e.g. one profit centre under two company codes) are data problems;
  // lower down, e.g. one product line under several profit centres, is normal and simply repeats under each parent
  structure.problems = structure.exceptions.filter((e) => ['Entity', 'Company code', 'Sales org'].includes(e.parent));
  const MAX_CHILDREN = 8;
  const buildTree = (curRows, prevRows, depth) => {
    if (depth >= levels.length || !curRows.length) return [];
    const lv = LEVEL[levels[depth]];
    // an empty value (e.g. no sales org, no profit centre for G367) skips the level instead of adding a blank row
    if (curRows.every((r) => !lv.of(r))) return buildTree(curRows, prevRows, depth + 1);
    const nodes = groupBy(curRows, (r) => lv.of(r) || '(not set)').sort(byValue).map((g) => {
      const pr = prevRows.filter((r) => (lv.of(r) || '(not set)') === g.key);
      let node = { label: g.key, level: lv.name, n: g.n, v: g.v, prevN: pr.length, tat: avgTat(g.rows), children: buildTree(g.rows, pr, depth + 1) };
      // one child with the same invoices = the same thing again: show it on the same line
      while (node.children.length === 1 && node.children[0].n === node.n) {
        const c = node.children[0];
        node = { ...node, label: `${node.label} › ${c.label}`, level: `${node.level} › ${c.level}`, children: c.children, more: c.more };
      }
      return node;
    });
    const shown = nodes.slice(0, MAX_CHILDREN);
    if (nodes.length > MAX_CHILDREN) {
      const rest = nodes.slice(MAX_CHILDREN);
      shown.push({ label: `+ ${rest.length} more`, level: lv.name, n: sum(rest, (x) => x.n), v: sum(rest, (x) => x.v), prevN: null, tat: null, children: [] });
    }
    return shown;
  };
  const tree = buildTree(cur, prev, 0);
  const mostCommon = (rows, f) => groupBy(rows, f).sort((a, b) => b.n - a.n || String(a.key).localeCompare(String(b.key)))[0]?.key || '';
  const customers = groupBy(cur, (r) => r.c).sort(byValue).slice(0, 15).map((g) => ({
    key: g.key, n: g.n, v: g.v, tat: avgTat(g.rows), prevN: prev.filter((r) => r.c === g.key).length,
    pc: mostCommon(g.rows, (r) => r.pc), pl: mostCommon(g.rows, (r) => r.pl), sap: mostCommon(g.rows, (r) => r.sap),
    trend: monthsBack.slice(-6).map((m) => scoped.filter((r) => r.c === g.key && r.d.slice(0, 7) === m.slice(0, 7)).length),
  }));
  const channels = groupBy(cur, channel).sort((a, b) => b.n - a.n);
  const managers = groupBy(cur, (r) => r.pm || 'Not recorded').sort((a, b) => b.n - a.n);
  // ----- pending invoices & follow-ups: every open item in the selection, whatever its date -----
  const today = opts.today || RULES.today || latest;
  const isOpen = (r) => /pend|hold|open|progress|query|block/i.test(r.st || '');
  const daysBetween = (x, y) => Math.round((ms(y) - ms(x)) / DAY);
  const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
  // dates written in "Reason for Pending" ("email sent on 23 June", "follow up on 3 July", "19th september")
  // a date without a year is read in order: on or after the previous date (and the received date), not after today
  const actionDates = (text, start) => {
    const found = new Set();
    let prev = start ? addDays(start, -7) : null;
    const lastYear = +today.slice(0, 4);
    const re = /\b(\d{1,2})(?:st|nd|rd|th)?\s*(?:of\s+)?(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?(?:,?\s*(\d{4}))?|\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?\b(?:,?\s*(\d{4}))?/gi;
    for (const m of String(text || '').matchAll(re)) {
      const day = +(m[1] || m[5]); const mon = MONTHS.indexOf(String(m[2] || m[4]).toLowerCase().slice(0, 3));
      if (!(day >= 1 && day <= 31) || mon < 0) continue;
      const at = (y) => `${y}-${String(mon + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      let yr = +(m[3] || m[6]) || 0;
      if (!yr) {
        // with an earlier date to go by: the first such date on or after it; otherwise the latest one up to today
        if (prev) for (let y = +prev.slice(0, 4); y <= lastYear && !yr; y++) if (at(y) >= prev && at(y) <= addDays(today, 1)) yr = y;
        if (!yr) yr = at(lastYear) <= addDays(today, 1) ? lastYear : lastYear - 1; // fallback: the latest such date up to today
      }
      if (iso(ms(at(yr))) !== at(yr)) continue; // skips impossible dates like 31 Sep
      found.add(at(yr));
      if (!prev || at(yr) > prev) prev = at(yr);
    }
    return [...found].sort();
  };
  // blocker groups from "Category" (or the reason when the category is empty); first matching rule wins
  const BLOCKERS = [
    ['Price / quantity / amount mismatch', /mismatch|variance|quantity|qty|price|amount|tax|tariff|freight/i],
    ['Invoice can\'t be raised on portal', /(unable|cannot|can not|not able)\b.*invoice/i], // e.g. the tracker category "Unable to ... invoice"
    ['PO / PO lines missing on portal', /\bpo\b|purchase order/i],
    ['Portal access / setup', /access|migrat|coupa|oracle|ariba|login|regist|portal/i],
  ];
  // the standard category (set when the data is saved) decides the group; older rows fall back to the rules above
  const GROUP_OF = { 'PO not available on portal': 'PO issue on portal', 'PO lines not available on portal': 'PO issue on portal',
    'PO cancelled or closed': 'PO issue on portal', 'PO line and invoice line mismatch': 'Invoice vs PO mismatch',
    'Price and quantity mismatch': 'Invoice vs PO mismatch', 'Quantity mismatch': 'Invoice vs PO mismatch', 'Price mismatch': 'Invoice vs PO mismatch',
    'Amount, tax or freight mismatch': 'Invoice vs PO mismatch', 'No portal access / portal migration': 'Portal access',
    'Unable to submit invoice on portal': 'Submission issue', Other: 'Other' };
  const blockerOf = (r) => {
    if (r.sc && GROUP_OF[r.sc]) return GROUP_OF[r.sc];
    const t = r.cat || r.why || ''; if (!t) return 'No reason given';
    return (BLOCKERS.find(([, re]) => re.test(t)) || ['Other'])[0];
  };
  const open = scopedAny.filter(isOpen).map((r) => {
    const start = r.rd || r.ad || r.d;
    const acts = actionDates(r.why, start);
    const last = acts[acts.length - 1] || null;
    const age = start ? Math.max(0, daysBetween(start, today)) : null;
    const sinceLast = last ? Math.max(0, daysBetween(last, today)) : null;
    return { ...r, age, last, sinceLast, followUps: acts.length, blocker: blockerOf(r), category: r.sc || r.cat || '',
      due: sinceLast !== null ? sinceLast >= RULES.followUpDays : (age !== null && age >= RULES.followUpDays) };
  });
  const avgOf = (rows, f) => { const x = rows.map(f).filter((v) => v !== null && v !== undefined); return x.length ? sum(x, (v) => v) / x.length : null; };
  const BUCKETS = [[0, 7, '0–7 days'], [8, 15, '8–15 days'], [16, 30, '16–30 days'], [31, 60, '31–60 days'], [61, 90, '61–90 days'], [91, 1e9, 'Over 90 days']];
  const pendingStats = (rows) => ({ n: rows.length, v: sum(rows, (r) => num(r.v)), due: rows.filter((r) => r.due).length, avgAge: avgOf(rows, (r) => r.age),
    oldest: Math.max(0, ...rows.map((r) => r.age || 0)) });
  // completed in the period = uploaded in the period (received date when there is no upload date)
  const closedTat = scoped.filter((r) => !isOpen(r) && r.st && (r.ud || r.d) >= from && (r.ud || r.d) <= to).map((r) => {
    const t = r.ud && (r.rd || r.ad) ? daysBetween(r.rd || r.ad, r.ud) : (r.tt !== '' && r.tt !== null && r.tt !== undefined && Number.isFinite(+r.tt) ? +r.tt : null);
    return { ...r, tat2: t !== null && t >= 0 ? t : null };
  }).filter((r) => r.tat2 !== null);
  const median = (x) => { if (!x.length) return null; const y = [...x].sort((p, q) => p - q); const m = Math.floor(y.length / 2); return y.length % 2 ? y[m] : (y[m - 1] + y[m]) / 2; };
  const pending = {
    today, rules: { followUpDays: RULES.followUpDays },
    total: pendingStats(open),
    ageing: BUCKETS.map(([lo, hi, label]) => { const rows = open.filter((r) => r.age !== null && r.age >= lo && r.age <= hi); return { key: label, n: rows.length, v: sum(rows, (r) => num(r.v)) }; }),
    blockers: groupBy(open, (r) => r.blocker).map((g) => ({ key: g.key, ...pendingStats(g.rows),
      categories: groupBy(g.rows, (r) => r.sc || r.cat || '').sort((a, b) => b.n - a.n).map((c) => ({ key: c.key, n: c.n, v: c.v })) })).sort((a, b) => b.v - a.v),
    owners: groupBy(open, (r) => r.ub || 'Not recorded').map((g) => ({ key: g.key, ...pendingStats(g.rows) })).sort((a, b) => b.n - a.n),
    companies: groupBy(open, (r) => r.cc || 'UNKNOWN').map((g) => ({ key: g.key, ...pendingStats(g.rows) })).sort((a, b) => b.v - a.v),
    actNow: [...open].sort((a, b) => (b.due - a.due) || ((b.age || 0) - (a.age || 0)) || (num(b.v) - num(a.v))).slice(0, 15),
    noDateInReason: open.filter((r) => !r.last).length,
    completed: { n: closedTat.length, avg: avgOf(closedTat, (r) => r.tat2), median: median(closedTat.map((r) => r.tat2)),
      owners: groupBy(closedTat, (r) => r.ub || 'Not recorded').map((g) => ({ key: g.key, n: g.n, avg: avgOf(g.rows, (r) => r.tat2) })).sort((a, b) => b.n - a.n) },
  };

  // entries still to be filled in (or that contradict each other), all rows in the selection
  const fillIn = [
    ['No status', (r) => !r.st],
    ['Pending without a reason', (r) => isOpen(r) && !r.why && !r.cat],
    ['Pending without a category', (r) => isOpen(r) && !r.cat && !!r.why],
    ['Pending without an owner (Uploaded by)', (r) => isOpen(r) && !r.ub],
    ['Pending but has an upload date', (r) => isOpen(r) && !!r.ud],
    ['Completed without upload date or TAT', (r) => r.st === 'Completed' && !r.ud && (r.tt === '' || r.tt === null || r.tt === undefined)],
  ].map(([label, test]) => { const hit = scopedAny.filter(test); return { label, n: hit.length, examples: hit.slice(0, 8).map((r) => String(r.i)) }; }).filter((x) => x.n);
  const quality = {
    fillIn,
    noValue: cur.filter((r) => !num(r.v)).length,
    repeated: groupBy(cur, (r) => String(r.i)).filter((g) => g.n > 1).map((g) => g.key),
    allocatedBeforeReceived: cur.filter((r) => r.rd && r.ad && r.ad < r.rd).length,
  };

  // ----- invoice distribution view: by area (La Prairie / Charleroi / Clearwater) and company code -----
  const areaOf = (r) => ENTITY[r.cc] || (r.cc ? 'OTHER' : 'NO COMPANY CODE');
  const AREAS = [...new Set([...Object.values(ENTITY), ...scopedAny.map(areaOf)])].filter((x) => scopedAny.some((r) => areaOf(r) === x));
  const isDone = (r) => r.st === 'Completed';
  const doneInPeriod = scopedAny.filter((r) => isDone(r) && (r.ud || r.d) >= from && (r.ud || r.d) <= to);
  const distRow = (key, keep) => {
    const rec = cur.filter(keep); const op = open.filter(keep); const dn = doneInPeriod.filter(keep);
    return { key, received: rec.length, receivedV: sum(rec, (r) => num(r.v)), distributed: dn.length, receivedDone: rec.filter(isDone).length,
      open: op.length, openV: sum(op, (r) => num(r.v)), due: op.filter((r) => r.due).length, avgAge: avgOf(op, (r) => r.age), oldest: Math.max(0, ...op.map((r) => r.age || 0)) };
  };
  const byArea = AREAS.map((ar) => ({ ...distRow(ar, (r) => areaOf(r) === ar),
    codes: [...new Set(scopedAny.filter((r) => areaOf(r) === ar).map((r) => r.cc || ''))].sort().map((c) => distRow(c || '(none)', (r) => areaOf(r) === ar && (r.cc || '') === c)) }));
  const kpis = { ...distRow('All', () => true), avgTatDone: pending.completed.avg };
  const whereOf = (rows) => groupBy(rows, (r) => `${areaOf(r)} ${r.cc || ''}`.trim()).sort((x, y) => y.n - x.n).map((g) => `${g.key}: ${g.n}`);
  const rootCauses = pending.blockers.map((b) => {
    const rows = open.filter((r) => r.blocker === b.key);
    return { ...b, where: whereOf(rows),
      categories: groupBy(rows, (r) => r.category || '').sort((x, y) => y.n - x.n).map((g) => ({ key: g.key, n: g.n, v: g.v, due: g.rows.filter((r) => r.due).length,
        avgAge: avgOf(g.rows, (r) => r.age), oldest: Math.max(0, ...g.rows.map((r) => r.age || 0)), where: whereOf(g.rows) })) };
  });
  const ageingByArea = pending.ageing.map((b, i) => {
    const [lo, hi] = [[0, 7], [8, 15], [16, 30], [31, 60], [61, 90], [91, 1e9]][i];
    const inB = (r) => r.age !== null && r.age >= lo && r.age <= hi;
    return { key: b.key, n: b.n, v: b.v, areas: AREAS.map((ar) => open.filter((r) => inB(r) && areaOf(r) === ar).length) };
  });
  const noAge = open.filter((r) => r.age === null).length;
  // the last 8 weeks up to the latest data (never empty future weeks)
  const lastWeek = weekStart(to < latest ? to : latest);
  const weeks8 = Array.from({ length: 8 }, (_, k) => addDays(lastWeek, -7 * (7 - k)));
  const weeklyByArea = weeks8.map((w) => { const rows = scoped.filter((r) => r.d >= w && r.d <= addDays(w, 6));
    return { key: w, n: rows.length, v: sum(rows, (r) => num(r.v)), areas: AREAS.map((ar) => rows.filter((r) => areaOf(r) === ar).length) }; });
  const heatByArea = AREAS.filter((ar) => ar !== 'NO COMPANY CODE').map((ar) => ({ area: ar, months: monthsBack.slice(-6).map((m) => ({ key: m.slice(0, 7),
    cells: Array.from({ length: 31 }, (_, i) => scoped.filter((r) => areaOf(r) === ar && r.d.slice(0, 7) === m.slice(0, 7) && +r.d.slice(8, 10) === i + 1).length) })) }));
  const GROUP_ORDER = ['PO issue on portal', 'Invoice vs PO mismatch', 'Portal access', 'Submission issue', 'Other', 'No reason given'];
  const pendingList = [...open].map((r) => ({ ...r, area: areaOf(r) })).sort((x, y) => {
    const gx = GROUP_ORDER.indexOf(x.blocker); const gy = GROUP_ORDER.indexOf(y.blocker);
    return ((gx < 0 ? 99 : gx) - (gy < 0 ? 99 : gy)) || String(x.category).localeCompare(String(y.category)) || ((y.age ?? -1) - (x.age ?? -1)) || (num(y.v) - num(x.v));
  });
  const distribution = { areas: AREAS, kpis, byArea, rootCauses, ageingByArea, noAge, weeklyByArea, heatByArea, pendingList };

  return {
    label, type, from, to, first, latest, cc, cust, pcSel, plSel, profitCentres, productLines, tree, structure, pending, distribution, total, prevTotal, avgTat: avgTat(cur), baseN: base.length,
    nChange: change(total.n, prevTotal.n), vChange: change(total.v, prevTotal.v),
    watch, monthly, weekly, heat, weekday, forecast, companies, customers, channels, managers, quality,
  };
}

function render(a) {
  if (a.empty) return '<p>No data for this selection.</p>';
  const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
