      return header + `<tr>${td(esc(r.i))}${td(nw(`${r.area} / ${r.cc || '–'}`))}${td(esc(r.pc || '–'))}${td(esc(r.pl || '–'))}${td(esc(r.bt || '–'))}${td(esc(r.c))}${td(nw(money(nv(r.v))), 1)}${ageCell(r.age)}` +
